import { isUndefined } from 'lodash-es';
import { useCallback } from 'react';

import { useCanvas } from '../../../../core/components/canvas/hooks/useCanvas.js';

interface CanvasSquareRendererProps {
  x: number;
  y: number;
  width: number;
  fillColor: string;
  strokeColor?: 'transparent' | string;
  radius?: number;
}

export const CanvasSquareRenderer = (props: CanvasSquareRendererProps) => {
  const { x, y, width, fillColor, strokeColor, radius = 0 } = props;

  const draw = useCallback(
    (ctx: CanvasRenderingContext2D) => {
      ctx.moveTo(x, y);
      ctx.beginPath();
      ctx.roundRect(x, y, width, width, radius);

      if (strokeColor === 'transparent') {
        ctx.globalCompositeOperation = 'destination-out';
        ctx.stroke();
        ctx.globalCompositeOperation = 'source-over';
      } else if (!isUndefined(strokeColor)) {
        ctx.strokeStyle = strokeColor;
        ctx.stroke();
      }

      ctx.fillStyle = fillColor;
      ctx.fill();

      return false;
    },
    [x, y, width, fillColor, strokeColor],
  );

  useCanvas('honeycomb-square', draw);

  return null;
};

CanvasSquareRenderer['displayName'] = 'CanvasSquareRenderer';
